import{_ as o,l as n,o as e,c as l,v as t,p as s,x as i,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"财富分布与帕累托尾","description":"","frontmatter":{"title":"财富分布与帕累托尾","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/wealth-distribution-pareto.md","filePath":"econ/wealth-distribution-pareto.md","lastUpdated":1789023840000}'),c={name:"econ/wealth-distribution-pareto.md"};function E(B,a,A,m,u,_){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="财富分布与帕累托尾" tabindex="-1">财富分布与帕累托尾 <a class="header-anchor" href="#财富分布与帕累托尾" aria-label="Permalink to &quot;财富分布与帕累托尾&quot;">​</a></h1><div class="epigraph"><p>Aiyagari 的右尾太薄；更厚的尾要靠收益异质、创业或 $r$ 与增长率的差在随机乘性过程里放大。</p><footer>—— Pareto；Gabaix 对幂律；Benhabib, Bisin and Zhu；Piketty and Zucman 的国民账户财富</footer></div><p><a href="/econ/krusell-smith">上一课</a>说明均值或可预报价格。数据里的财富极右尾很厚，政策与 \\(r\\) 的变动主要打在那里。本课缺口是<strong>尾从哪来</strong>，不是再跑一遍 KS 的 \\(R^2\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>劳动收入即使很持久，加上线性储蓄政策，财富分布往往仍是薄尾。幂律（Pareto）出现在乘性随机增长：\\(\\log\\) 财富有正漂移时被反射或死亡抵消，得到 \\(P(w\\gt x)\\propto x^{-\\alpha}\\)。Benhabib–Bisin–Zhu：异质收益率、资本收入风险、遗产，比劳动收入更能造尾。Piketty：\\(r\\gt g\\) 放大已有财富，但是否幂律还看冲击与再分配。缺口是把「基尼」从稳态 Aiyagari 的失败，升级成对尾机制的选择。</p><p><span class="marginnote">Gabaix, <em>Annual Review of Economics</em> 2009，幂律综述。Saez–Zucman 与 Piketty–Zucman 给跨国尾指数。本课不把税收最优一次写完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>诊断：在双对数图上看财富的 complementary CDF 是否直线。模型：在 Aiyagari 上加（i）异质 \\(r\\)（投资技能、私募），（ii）创业占优，(iii) 随机死亡与利他遗产，(iv) 偏好异质。校准靶从劳动收入矩换成财富份额（前 1%、0.1%）。KS 的低维预报在极尾变重要时可能不够：极富者的资本供给弹性决定 \\(r\\)。</p>',8)),(e(),s(h,null,{default:i(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAB%5B%22%E4%BB%85%E5%8A%B3%E5%8A%A8%E6%94%B6%E5%85%A5%E9%A3%8E%E9%99%A9%22%5D%20--%3E%20THIN%5B%22%E8%96%84%E5%B0%BE%22%5D%0A%20%20RET%5B%22%E6%94%B6%E7%9B%8A%E5%BC%82%E8%B4%A8%20%2F%20%E5%88%9B%E4%B8%9A%22%5D%20--%3E%20FAT%5B%22%E5%B8%95%E7%B4%AF%E6%89%98%E5%B0%BE%22%5D%0A%20%20RG%5B%22r%3Eg%20%E4%B9%98%E6%80%A7%22%5D%20--%3E%20FAT%0A%20%20FAT%20--%3E%20TOP%5B%22%E9%A1%B6%E5%B1%82%E8%B4%A2%E5%AF%8C%E4%BB%BD%E9%A2%9D%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与周期：尾厚使总量资本更集中，MPC 加总更接近富人的低 MPC——除非住房与流动性把穷人绑在约束上（后课 HANK 的两资产）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是乘性放大加某种重置。没有重置（死亡、破产、税收），方差爆炸，没有平稳尾。没有乘性（纯加性劳动储蓄），尾指数太大（太薄）。\\(r-g\\) 是漂移：更大则更厚尾、更慢的社会流动。但 \\(r\\) 在一般均衡里是内生的，把数据里的 \\(r\\gt g\\) 直接当外生常数会重复计算——再后课专门钉。</p><p>测量：资本化法与调查对顶层敏感不同。模型对错要声明数据口径。</p><p><span class="marginnote">Pareto 1896 对收入；现代财富尾见 Klass 等、Vermeulen 对顶层修正。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写最优资本税（Atkinson–Stiglitz、Piketty 税）。不把企业家金融写成公司金融课。也不用量化栏的因子模型解释个人财富。代际流动下一课才从人力资本接。</p><p>后课默认：厚尾需要乘性收益或创业，不只是 Aiyagari 劳动风险。下一课：把不完全市场接到有名义刚性的总需求——HANK。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>标准不完全市场稳态尾偏薄。</li><li>帕累托尾来自乘性财富过程加重置。</li><li>尾决定谁供给资本、加总 MPC 的权重。</li><li>出处：Gabaix 幂律综述；Benhabib, Bisin and Zhu；Piketty–Zucman。</li></ul>',10))])}const f=o(c,[["render",E]]);export{P as __pageData,f as default};
